-- PNJ d'ambiance : cavaliers immobiles en extérieur (demande de l'utilisateur du 28/10/2026). Modèles des montures
-- terrestres de joueur : sorts de Spell.dbc avec les auras « monté » (78) et « vitesse montée » (32), sans vol (206, 207),
-- appris par un objet ; la créature de l'aura donne le modèle.
USE acore_world;

CREATE TABLE solazeroth_ambiance_montures (
    display INT UNSIGNED NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TEMPORARY TABLE solazeroth_tmp_montures (spell INT UNSIGNED, entry INT UNSIGNED);

SELECT DISTINCT m.CreatureDisplayID FROM solazeroth_tmp_montures t
JOIN item_template i ON i.spellid_2 = t.spell
JOIN creature_template_model m ON m.CreatureID = t.entry AND m.Idx = 0;

DROP TEMPORARY TABLE solazeroth_tmp_montures;
